    centers=[(r,c,grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] not in (0,3)]
    for r,c,color in centers:
        for j in range(w):
            if grid[r][j]==0: out[r][j]=color
    # A blank 3-cross casts a zero vertical line; its 3 markers remain.
    blank_cols=[]
    for r in range(1,h-1):
        for c in range(1,w-1):
            if grid[r][c]==0 and all(grid[r+dr][c+dc]==3 for dr,dc in ((-1,0),(1,0),(0,-1),(0,1))):
                blank_cols.append(c)
    for c in blank_cols:
        for r in range(h):
            if grid[r][c]==0: out[r][c]=0
    for r,c,color in centers:
        for i in range(h):
            if grid[i][c]==0: out[i][c]=color
    return out
