def transform_v3(grid):
    h,w=len(grid),len(grid[0]); out=[r[:] for r in grid]
    centers=[(r,c,grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] not in (0,3)]
    blank_cols={c for r in range(1,h-1) for c in range(1,w-1) if grid[r][c]==0 and all(grid[r+dr][c+dc]==3 for dr,dc in ((-1,0),(1,0),(0,-1),(0,1)))}
    def ray(r,c,color,dr,dc,own):
        i,j=r+dr,c+dc
        while 0<=i<h and 0<=j<w:
            if grid[i][j]!=0:
                if (i,j) not in own:
                    break
            elif dc==0 or j not in blank_cols:
                out[i][j]=color
            i+=dr; j+=dc
    # Horizontal rays first; 3 arms of other crosses block a ray, while the emitting cross's arms do not.
    for r,c,color in centers:
        own={(r+dr,c+dc) for dr,dc in ((-1,0),(1,0),(0,-1),(0,1))}
        ray(r,c,color,0,-1,own); ray(r,c,color,0,1,own)
    # Vertical rays are layered on top of horizontal rays.
    for r,c,color in centers:
        own={(r+dr,c+dc) for dr,dc in ((-1,0),(1,0),(0,-1),(0,1))}
        ray(r,c,color,-1,0,own); ray(r,c,color,1,0,own)
    return out
